export type ParsedCheckInTokenInstruction<
  TProgram extends string = typeof SAFECARD_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    owner: TAccountMetas[0];
    card: TAccountMetas[1];
    merchant: TAccountMetas[2];
    /** 商家钱包，只用来确认收款账户归属 */
    authority: TAccountMetas[3];
    mint: TAccountMetas[4];
    stats: TAccountMetas[5];
    vault: TAccountMetas[6];
    merchantTokenAccount: TAccountMetas[7];
    tokenProgram: TAccountMetas[8];
  };
  data: CheckInTokenInstructionData;
};

export function parseCheckInTokenInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedCheckInTokenInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 9) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 9,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      owner: getNextAccount(),
      card: getNextAccount(),
      merchant: getNextAccount(),
      authority: getNextAccount(),
      mint: getNextAccount(),
      stats: getNextAccount(),
      vault: getNextAccount(),
      merchantTokenAccount: getNextAccount(),
      tokenProgram: getNextAccount(),
    },
    data: getCheckInTokenInstructionDataDecoder().decode(instruction.data),
  };
}
